    for x,label in zip(xs,labels):out+=f'<rect x="{x-65}" y="20" width="130" height="34" rx="5" fill="#193d3b"/><text x="{x}" y="42" text-anchor="middle" fill="white" font-size="12">{label}</text><line x1="{x}" y1="54" x2="{x}" y2="450" stroke="#b8cdbf" stroke-dasharray="4 5"/>'
    for y,a,b,label in [(95,0,1,'Commit relationship + outbox + audit'),(140,1,0,'Home acknowledgement'),(185,2,1,'Read current policy and recipient'),(230,2,3,'Resolve entity → store; evaluate'),(275,3,2,'Allow fields / deny with reason'),(320,2,4,'Approved scoped projection only'),(365,4,4,'Recheck + inbox + fence + copy'),(410,4,2,'Commit receipt; complete outbox')]:
        x1,x2=xs[a],xs[b]
        if a==b:out+=f'<path d="M{x1},{y-5} h65 v25 h-65" fill="none" stroke="#38725d" marker-end="url(#arrow)"/><text x="{x1-12}" y="{y}" text-anchor="end" font-size="11" fill="#365e4a">{label}</text>'
